      "category": "training_strategy",
      "rationale": "Halve the existing learning rate across all four datasets to reduce validation oscillation after recurrent gate normalization. Preserve all other training settings, architecture, loss, routing, and single-model checkpoints.",
      "edits": [
        {
          "find": "LR            = float(os.environ.get(\"GRU4REC_LR\", \"1e-3\"))",
          "replace": "LR            = 0.5 * float(os.environ.get(\"GRU4REC_LR\", \"1e-3\"))"
        }
      ]
    }
  ],
  "change_summary": "Multiply the configured learning rate by 0.5 for every category; default learning rate becomes 5e-4."
}
